{"function": "() => {
    // Find the heading "Studio albums"
    const headings = Array.from(document.querySelectorAll('h3'));
    const studioHeading = headings.find(h => h.textContent.includes('Studio albums'));
    if (!studioHeading) return null;
    // Find the next table after this heading
    let elem = studioHeading.nextElementSibling;
    while (elem && elem.tagName !== 'TABLE') {
        elem = elem.nextElementSibling;
    }
    if (!elem) return null;
    const table = elem;
    const rows = table.querySelectorAll('tr');
    const data = [];
    for (let i = 1; i < rows.length; i++) { // skip header row
        const cells = rows[i].querySelectorAll('td');
        if (cells.length >= 2) {
            const year = cells[0].textContent.trim();
            const details = cells[1].textContent.trim();
            data.push({year, details});
        }
    }
    return data;
}"}

